"const trek = ref(null)\nconst localFood = ref([])\nconst restaurants = ref([])\nconst agencies = ref([])\nconst selectedAgencyId = ref(null)\nconst booking = ref(false)\nconst bookMsg = ref('')\nconst bookErr = ref('')\nconst acceptPledge = ref(false)\n\nconst trekMantra = computed(() => {\n  if (!trek.value) return ''\n  const name = trek.value.name.toLowerCase()\n  if (name.includes('kedarnath')) return '“ॐ नमः शिवाय”'\n  if (name.includes('brahmatal')) return '“ॐ ब्रह्मणे नमः”'\n  if (name.includes('hemkund')) return '“सतनाम श्री वाहेगुरु”'\n  if (name.includes('chadar')) return '“ॐ मणि पद्मे हूँ”'\n  if (name.includes('sandakphu')) return '“बुद्धं शरणं गच्छामि”'\n  if (name.includes('amarnath')) return '“जय बाबा बर्फानी”'\n  if (name.includes('tungnath')) return '“हर हर महादेव”'\n  if (name.includes('kailash')) return '“ॐ नमः शिवाय”'\n  return '“सत्यं शिवं सुन्दरम्”'\n})"